  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ==========================\n// ผู้ใช้งานระบบ (อาจารย์/บุคลากร, ผู้ควบคุมหน่วยยานพาหนะ, ผู้ดูแลระบบ)\n// ==========================\nenum Role {\n  USER // อาจารย์ / บุคลากรผู้ขอใช้รถ\n  STAFF // ผู้ควบคุมหน่วยยานพาหนะ / เจ้าหน้าที่\n  ADMIN // ผู้ดูแลระบบ\n}\n\nmodel User {\n  id         Int      @id @default(autoincrement())\n  name       String\n  email      String   @unique\n  password   String\n  phone      String?\n  department String? // ภาควิชา/สาขาวิชา/หน่วยงาน\n  role       Role     @default(USER)\n  avatarUrl  String?  @db.Text // เก็บเป็น base64 data URL ของรูปโปรไฟล์\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  bookings Booking[] @relation(\"RequesterBookings\")\n\n  @@map(\"users\")\n}\n\n// ==========================\n// รถตู้\n// ==========================\nenum VehicleStatus {\n  AVAILABLE\n  IN_USE\n  MAINTENANCE\n}\n\nmodel Vehicle {\n  id          Int           @id @default(autoincrement())\n  plateNumber String        @unique\n  brand       String?\n  model       String?\n  seats       Int?\n  status      VehicleStatus @default(AVAILABLE)\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  bookings Booking[]\n\n  @@map(\"vehicles\")\n}\n\n// ==========================\n// พนักงานขับรถ\n// ==========================\nenum DriverStatus {\n  AVAILABLE\n  ON_DUTY\n  OFF\n}\n\nmodel Driver {\n  id        Int          @id @default(autoincrement())\n  name      String\n  phone     String\n  status    DriverStatus @default(AVAILABLE)\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  bookings Booking[]\n\n  @@map(\"drivers\")\n}\n\n// ==========================\n// คำขอใช้รถ (การจอง)\n// ==========================\nenum BookingPurpose {\n  SUPERVISION // นิเทศนักศึกษาฝึกประสบการณ์วิชาชีพครู/สอบสอน\n  MEETING // ประชุม/อบรม/สัมมนา\n  PICKUP_SPEAKER // รับ-ส่งอาจารย์พิเศษหรือวิทยากร\n  STUDY_VISIT // นำนักศึกษาไปศึกษาดูงาน\n  OTHER // อื่น ๆ\n}\n\nenum TripType {\n  ROUND_TRIP // ไป-กลับ\n  ONE_WAY // เที่ยวเดียว\n}\n\nenum BookingStatus {\n  PENDING // รออนุมัติ\n  APPROVED // อนุมัติแล้ว\n  REJECTED // ปฏิเสธ\n  COMPLETED // เดินทางเสร็จสิ้น\n  CANCELLED // ยกเลิกโดยผู้ขอ\n}\n\nmodel Booking {\n  id Int @id @default(autoincrement())\n\n  requester   User @relation(\"RequesterBookings\", fields: [requesterId], references: [id])\n  requesterId Int\n\n  purpose       BookingPurpose\n  purposeDetail String? // รายละเอียดเพิ่มเติม กรณีเลือก OTHER\n\n  destination    String // สถานที่ไปราชการ\n  street         String? // ถนน\n  province       String? // จังหวัด\n  route          String? // เส้นทางที่ขอให้รถผ่าน\n  startDateTime  DateTime // วัน-เวลาไป\n  endDateTime    DateTime // วัน-เวลากลับ\n  pickupLocation String? // จุดที่ขอให้รถออกจาก (ที่จอดรถคณะฯ/สำนักงานอธิการบดี/อื่น ๆ)\n  tripType       TripType @default(ROUND_TRIP)\n\n  speakerName  String? // ชื่อวิทยากร (กรณีรับ-ส่งวิทยากร)\n  speakerPhone String? // เบอร์โทรศัพท์วิทยากร\n\n  controllerName  String? // ผู้ควบคุมการไปราชการ\n  controllerPhone String?\n\n  budgetSource String? // แหล่งเบิกจ่ายงบประมาณ\n\n  status       BookingStatus @default(PENDING)\n  rejectReason String?\n\n  vehicle   Vehicle? @relation(fields: [vehicleId], references: [id])\n  vehicleId Int?\n\n  driver   Driver? @relation(fields: [driverId], references: [id])\n  driverId Int?\n\n  approvedById Int? // id ของ staff ที่อนุมัติ/ปฏิเสธ\n\n  passengers Passenger[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"bookings\")\n}\n\n// ==========================\n// รายชื่อผู้ร่วมเดินทาง (สูงสุดไม่เกิน 10 คนต่อคัน)\n// ==========================\nmodel Passenger {\n  id        Int     @id @default(autoincrement())\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  bookingId Int\n  name      String\n\n  @@map(\"passengers\")\n}\n",
